import unittest

class MergeIntervalsTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_unsorted_overlap_and_touching(self):
        self.assertEqual(merge_intervals([[8, 10], [1, 3], [3, 5], [12, 13]]), [[1, 5], [8, 10], [12, 13]])

    def test_nested_and_duplicate(self):
        self.assertEqual(merge_intervals([[2, 7], [3, 4], [2, 7]]), [[2, 7]])

    def test_input_is_not_mutated(self):
        data = [[5, 7], [1, 2]]
        before = [row[:] for row in data]
        merge_intervals(data)
        self.assertEqual(data, before)

if __name__ == '__main__':
    unittest.main(verbosity=2)

